import{_ as o,o as t,c as l,a5 as d}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"logback-spring.xml","description":"","frontmatter":{"title":"logback-spring.xml","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","核心API","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第三部分：核心 API/07-异常与线程/logback-spring.xml.md","filePath":"posts/java快速入门/第三部分：核心 API/07-异常与线程/logback-spring.xml.md"}'),c={name:"posts/java快速入门/第三部分：核心 API/07-异常与线程/logback-spring.xml.md"};function n(p,e,g,r,a,i){return t(),l("div",null,[...e[0]||(e[0]=[d("<div><p>这个<code>logback-spring.xml</code>文件配置了Logback日志记录系统的行为。以下是该配置文件的详细作用和解释：</p><p>完整示例： &lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;configuration&gt; &lt;!-- 控制台输出 --&gt; &lt;appender name=&quot;console&quot; class=&quot;ch.qos.logback.core.ConsoleAppender&quot;&gt; &lt;encoder&gt; &lt;pattern&gt;%d{yyyy-MM-dd HH:mm:ss} %-5level %logger{36} - %msg%n&lt;/pattern&gt; &lt;/encoder&gt; &lt;/appender&gt; &lt;!-- 文件输出 --&gt; &lt;appender name=&quot;file&quot; class=&quot;ch.qos.logback.core.FileAppender&quot;&gt; &lt;file&gt;app.log&lt;/file&gt; &lt;encoder&gt; &lt;pattern&gt;%d{yyyy-MM-dd HH:mm:ss} %-5level %logger{36} - %msg%n&lt;/pattern&gt; &lt;/encoder&gt; &lt;/appender&gt; &lt;!-- 为特定包设置日志级别 --&gt; &lt;logger name=&quot;com.hunanminsheng.zhslappbackend&quot; level=&quot;debug&quot; /&gt; &lt;!-- 根日志记录器，配置日志级别和附加器 --&gt; &lt;root level=&quot;info&quot;&gt; &lt;appender-ref ref=&quot;console&quot; /&gt; &lt;appender-ref ref=&quot;file&quot; /&gt; &lt;/root&gt; &lt;/configuration&gt;</p><p>顶部声明 &lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;configuration&gt;</p><ul><li>这是XML文件的声明，定义了XML的版本和编码方式。</li></ul><p>&lt;configuration&gt;`标签是Logback配置文件的根元素。</p><p>控制台输出（ConsoleAppender） &lt;appender name=&quot;console&quot; class=&quot;ch.qos.logback.core.ConsoleAppender&quot;&gt; &lt;encoder&gt; &lt;pattern&gt;%d{yyyy-MM-dd HH:mm:ss} %-5level %logger{36} - %msg%n&lt;/pattern&gt; &lt;/encoder&gt; &lt;/appender&gt;</p><p>&lt;appender&gt;<code>定义了一个日志输出器（appender），名为</code>console<code>，类型为</code>ch.qos.logback.core.ConsoleAppender`。</p><ul><li><code>ConsoleAppender</code>将日志消息输出到控制台（标准输出）。</li><li>&lt;encoder&gt;`定义了日志消息的编码方式。</li><li>&lt;pattern&gt;`定义了日志消息的格式： <ul><li><code>%d{yyyy-MM-dd HH:mm:ss}</code>：日志的时间戳，格式为<code>年-月-日 时:分:秒</code>。</li><li><code>%-5level</code>：日志级别，占5个字符宽度，左对齐。</li><li><code>%logger{36}</code>：日志记录器的名称，最多36个字符。</li><li><code>- %msg%n</code>：日志消息，<code>%n</code>表示换行。</li></ul></li></ul><p>文件输出（FileAppender） &lt;appender name=&quot;file&quot; class=&quot;ch.qos.logback.core.FileAppender&quot;&gt; &lt;file&gt;app.log&lt;/file&gt; &lt;encoder&gt; &lt;pattern&gt;%d{yyyy-MM-dd HH:mm:ss} %-5level %logger{36} - %msg%n&lt;/pattern&gt; &lt;/encoder&gt; &lt;/appender&gt;</p><ul><li>&lt;appender&gt;<code>定义了一个日志输出器（appender），名为</code>file<code>，类型为</code>ch.qos.logback.core.FileAppender`。</li><li><code>FileAppender</code>将日志消息输出到指定的文件。</li><li>&lt;file&gt;<code>指定了日志文件的路径，这里为</code>app.log`。</li><li>&lt;encoder&gt;`定义了日志消息的编码方式，与控制台输出相同。</li></ul><p>根日志记录器（Root Logger） &lt;root level=&quot;info&quot;&gt; &lt;appender-ref ref=&quot;console&quot; /&gt; &lt;appender-ref ref=&quot;file&quot; /&gt; &lt;/root&gt;</p><ul><li>&lt;root&gt;<code>定义了根日志记录器，</code>level=&quot;info&quot;<code>表示日志级别为</code>info`。</li><li>日志级别从低到高依次为：<code>TRACE</code>、<code>DEBUG</code>、<code>INFO</code>、<code>WARN</code>、<code>ERROR</code>。<code>info</code>级别会记录<code>INFO</code>及以上级别的日志消息。</li><li>&lt;appender-ref ref=&quot;console&quot; /&gt;<code>引用了前面定义的控制台输出器</code>console`。</li><li>&lt;appender-ref ref=&quot;file&quot; /&gt;<code>引用了前面定义的文件输出器</code>file`。</li></ul><p>整体作用</p><ul><li>这个配置文件定义了两个日志输出器，一个将日志输出到控制台，另一个将日志输出到文件<code>app.log</code>。</li><li>所有<code>info</code>级别及以上的日志消息都会被这两个输出器记录。</li><li>你可以根据需要调整日志级别、日志格式和输出位置（如文件路径）来满足具体需求。</li></ul><p>自定义日志级别 你可以根据需要为特定的包或类自定义日志级别。例如，如果你希望为<code>com.hunanminsheng.zhslappbackend</code>包设置<code>DEBUG</code>级别的日志记录，可以在<code> 这个配置文件将</code>com.hunanminsheng.zhslappbackend<code>包的日志级别设置为</code>DEBUG<code>，并将日志消息输出到控制台和文件</code>app.log`。</p></div>",1)])])}const q=o(c,[["render",n]]);export{u as __pageData,q as default};
